// src/app/product/[slug]/page.tsx

export default async function Page({ params }: { params: Promise<{ slug: string }> }) {
  // 1. You MUST await params in Next.js 15
  const { slug } = await params; 
  
  // Now this will show in your TERMINAL
  console.log("Fetching product with slug:", slug);

  const product = await getProductBySlug(slug);
  
  if (!product) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black text-white">
        <h1 className="text-3xl font-bold uppercase tracking-tighter italic">
          Product Not Found: {slug}
        </h1>
      </div>
    );
  }

  const similarProducts = await getSimilarProducts(product.category, product.id);

  return (
    <ProductPageMaster 
      product={product} 
      similarProducts={similarProducts} 
    />
  );
}